            "name": "Lachesis Kuss",
            "description": "Eingeschränkte Meisterschaft über das physische Alter: Der Vampir berührt das Ziel, konzentriert sich 1 Runde, gibt 2 Blutpunkte aus und würfelt Manipulation + Okkultismus (Schwierigkeit 4 + Widerstandsfähigkeit des Ziels bzw. Objektwert +4). Er erhöht oder verringert das Alter um bis zu 1 Woche (1 Erfolg), 1 Jahr (3), 1 Jahrhundert (5) bzw. 1 Jahrhundert pro Erfolg über 5; jeder angewandte Erfolg wird als nicht absorbierbarer tödlicher Schaden gegen ihn neu gewürfelt (Schwierigkeit gleich Temporis). Vampire verlieren 1 Blutpunkt pro Tag beschleunigter Alterung (Gefahr von Raserei und Starre), Lebewesen verhungern und verlieren ab dem 3. Tag 1 Widerstandsfähigkeit pro Tag bis zum Tod. Die Geschichte lässt sich nicht revidieren: Verjüngung führt höchstens zum Zustand der Erschaffung bzw. Geburt zurück, geistige und mystische Eigenschaften bleiben unverändert."
